//! The check of a written value against its key's whole schema, nested fields included: what
//! `SettingDef::check_value` (the light check of rb-settings, always run first) does for the key
//! itself, here for every field of a list or an object, so the settings window can show the
//! problem at the field (`/2/width`). The schemas are generated by schemars and inlined (no
//! `$ref`); `pattern` and `format` are left to the types, which `write` deserializes last.

use rb_ipc::SettingIssue;
use rb_util::json_pointer::escape;
use serde_json::Value;

/// The i18n keys of the reasons.
pub mod reason {
    /// The value has the wrong type.
    pub const TYPE: &str = "settings.rejected.type";
    /// Not one of the allowed values.
    pub const ENUM: &str = "settings.rejected.enum";
    /// Below the minimum.
    pub const MINIMUM: &str = "settings.rejected.minimum";
    /// Above the maximum.
    pub const MAXIMUM: &str = "settings.rejected.maximum";
    /// A required field is missing.
    pub const REQUIRED: &str = "settings.rejected.required";
    /// A field the schema does not know.
    pub const UNKNOWN_FIELD: &str = "settings.rejected.unknown_field";
}

/// How deep a value is followed; the settings nest three levels at most.
const MAX_DEPTH: usize = 16;

/// Every problem of `value` against `schema`, each with its JSON pointer below the key.
pub fn check(schema: &Value, value: &Value) -> Vec<SettingIssue> {
    let mut issues = Vec::new();
    walk(schema, value, "", 0, &mut issues);
    issues
}

fn walk(schema: &Value, value: &Value, at: &str, depth: usize, issues: &mut Vec<SettingIssue>) {
    if depth > MAX_DEPTH || !schema.is_object() {
        return;
    }
    for combinator in ["anyOf", "oneOf"] {
        if let Some(branches) = schema.get(combinator).and_then(Value::as_array) {
            let fits = branches.iter().any(|branch| {
                let mut found = Vec::new();
                walk(branch, value, at, depth + 1, &mut found);
                found.is_empty()
            });
            if !fits {
                issues.push(issue(at, reason::ENUM));
                return;
            }
        }
    }
    if let Some(expected) = schema.get("const")
        && expected != value
    {
        issues.push(issue(at, reason::ENUM));
        return;
    }
    let types: Vec<&str> = match schema.get("type") {
        Some(Value::String(one)) => vec![one.as_str()],
        Some(Value::Array(many)) => many.iter().filter_map(Value::as_str).collect(),
        _ => Vec::new(),
    };
    if !types.is_empty() && !types.iter().any(|kind| has_type(value, kind)) {
        issues.push(issue(at, reason::TYPE));
        return;
    }
    if let Some(allowed) = schema.get("enum").and_then(Value::as_array)
        && !allowed.contains(value)
    {
        issues.push(issue(at, reason::ENUM));
        return;
    }
    if let Some(number) = value.as_f64() {
        if schema
            .get("minimum")
            .and_then(Value::as_f64)
            .is_some_and(|minimum| number < minimum)
        {
            issues.push(issue(at, reason::MINIMUM));
        }
        if schema
            .get("maximum")
            .and_then(Value::as_f64)
            .is_some_and(|maximum| number > maximum)
        {
            issues.push(issue(at, reason::MAXIMUM));
        }
    }
    match value {
        Value::Array(items) => {
            if let Some(item_schema) = schema.get("items") {
                for (index, item) in items.iter().enumerate() {
                    walk(
                        item_schema,
                        item,
                        &format!("{at}/{index}"),
                        depth + 1,
                        issues,
                    );
                }
            }
        }
        Value::Object(fields) => object(schema, fields, at, depth, issues),
        _ => {}
    }
}

fn object(
    schema: &Value,
    fields: &serde_json::Map<String, Value>,
    at: &str,
    depth: usize,
    issues: &mut Vec<SettingIssue>,
) {
    let properties = schema.get("properties").and_then(Value::as_object);
    for required in schema
        .get("required")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(Value::as_str)
    {
        if !fields.contains_key(required) {
            issues.push(issue(
                &format!("{at}/{}", escape(required)),
                reason::REQUIRED,
            ));
        }
    }
    for (name, field) in fields {
        let path = format!("{at}/{}", escape(name));
        match properties.and_then(|properties| properties.get(name)) {
            Some(field_schema) => walk(field_schema, field, &path, depth + 1, issues),
            None => match schema.get("additionalProperties") {
                Some(Value::Bool(false)) => issues.push(issue(&path, reason::UNKNOWN_FIELD)),
                Some(extra @ Value::Object(_)) => walk(extra, field, &path, depth + 1, issues),
                _ => {}
            },
        }
    }
}

fn has_type(value: &Value, kind: &str) -> bool {
    match kind {
        "null" => value.is_null(),
        "boolean" => value.is_boolean(),
        "integer" => value.is_i64() || value.is_u64(),
        "number" => value.is_number(),
        "string" => value.is_string(),
        "array" => value.is_array(),
        "object" => value.is_object(),
        _ => true,
    }
}

fn issue(path: &str, message_key: &str) -> SettingIssue {
    SettingIssue {
        path: path.to_owned(),
        message_key: message_key.to_owned(),
    }
}

